SELECT COUNT(*)
FROM semantic_batch_job_chunks
WHERE batch_job_id = #{batchJobId}

SELECT COUNT(*)
FROM semantic_batch_job_chunks
WHERE batch_job_id = #{batchJobId}
  AND status = #{status}

SELECT chunk_id
FROM semantic_batch_job_chunks
WHERE batch_job_id = #{batchJobId}
  AND status = #{status}

mapper.update:
UPDATE semantic_batch_job_chunks
SET status = CASE WHEN status = 'SUBMITTED' THEN 'OUTPUT_READY' ELSE status END,
    output_ready_at = COALESCE(output_ready_at, CURRENT_TIMESTAMP)
WHERE batch_job_id = #{batchJobId}
  AND custom_id = #{customId}

UPDATE semantic_batch_job_chunks
SET status = 'FAILED',
    output_ready_at = COALESCE(output_ready_at, CURRENT_TIMESTAMP),
    error_code = #{errorCode},
    error_message = #{errorMessage}
WHERE batch_job_id = #{batchJobId}
  AND custom_id = #{customId}
